static const Demo_TrafficLight_State kParent[Demo_TrafficLight_StateCount] = {
    Demo_TrafficLight_State_None,   /* Off */
    Demo_TrafficLight_State_None,   /* Operating */
    Demo_TrafficLight_State_Operating,   /* Red */
    Demo_TrafficLight_State_Operating,   /* Green */
    Demo_TrafficLight_State_Operating,   /* Yellow */
    Demo_TrafficLight_State_None,   /* Flashing */
};
static const unsigned char kRegionOf[Demo_TrafficLight_StateCount] =   /* region that contains the state */ {
    0,   /* Off */
    0,   /* Operating */
    1,   /* Red */
    1,   /* Green */
    1,   /* Yellow */
    0,   /* Flashing */
};
static const unsigned char kFirstRegion[Demo_TrafficLight_StateCount] =   /* first own region */ {
    0,   /* Off */
    1,   /* Operating */
    0,   /* Red */
    0,   /* Green */
    0,   /* Yellow */
    0,   /* Flashing */
};
static const unsigned char kRegionsOf[Demo_TrafficLight_StateCount] =   /* number of own regions */ {
    0,   /* Off */
    1,   /* Operating */
    0,   /* Red */
    0,   /* Green */
    0,   /* Yellow */
    0,   /* Flashing */
};
static const char* const kStateNames[Demo_TrafficLight_StateCount] = {
    "Off",   /* Off */
    "Operating",   /* Operating */
    "Red",   /* Red */
    "Green",   /* Green */
    "Yellow",   /* Yellow */
    "Flashing",   /* Flashing */
};
static const char* const kEventNames[Demo_TrafficLight_EventCount] = {
    "Timer",
    "PedestrianRequest",
    "PowerOn",
    "PowerOff",
    "Fault",
    "Repair",
};
static const unsigned char kHistoryKind[Demo_TrafficLight_StateCount] =   /* 0 = none, 1 = shallow, 2 = deep */ {
    0,   /* Off */
    1,   /* Operating */
    0,   /* Red */
    0,   /* Green */
    0,   /* Yellow */
    0,   /* Flashing */
};

static size_t RegionOf(Demo_TrafficLight_State state) {
    return kRegionOf[state];
}

static size_t FirstRegionOf(Demo_TrafficLight_State state) {
    return kFirstRegion[state];
}

static size_t RegionsOf(Demo_TrafficLight_State state) {
    return kRegionsOf[state];
}

Demo_TrafficLight_State Demo_TrafficLight_ParentOf(Demo_TrafficLight_State state) {
    return state == Demo_TrafficLight_State_None ? Demo_TrafficLight_State_None : kParent[state];
}

const char* Demo_TrafficLight_StateName(Demo_TrafficLight_State state) {
    return state == Demo_TrafficLight_State_None ? "None" : kStateNames[state];
}

const char* Demo_TrafficLight_EventName(Demo_TrafficLight_Event event) {
    return kEventNames[event];
}

static void Trace(Demo_TrafficLight* m, Demo_TrafficLight_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

typedef void (*Handler)(Demo_TrafficLight* m);

static void Entry_Red(Demo_TrafficLight* m) {
    m->hooks->redOn(m->context);
}

static void Entry_Green(Demo_TrafficLight* m) {
    m->hooks->greenOn(m->context);
}

static void Entry_Yellow(Demo_TrafficLight* m) {
    m->hooks->yellowOn(m->context);
}

static void Entry_Flashing(Demo_TrafficLight* m) {
    m->hooks->flashOn(m->context);
}

static void Exit_Red(Demo_TrafficLight* m) {
    m->hooks->redOff(m->context);
}

static void Exit_Green(Demo_TrafficLight* m) {
    m->hooks->greenOff(m->context);
}

static void Exit_Yellow(Demo_TrafficLight* m) {
    m->hooks->yellowOff(m->context);
}

static void Exit_Flashing(Demo_TrafficLight* m) {
    m->hooks->flashOff(m->context);
}

static const Handler kEntry[Demo_TrafficLight_StateCount] = {
    NULL,   /* Off */
    NULL,   /* Operating */
    Entry_Red,   /* Red */
    Entry_Green,   /* Green */
    Entry_Yellow,   /* Yellow */
    Entry_Flashing,   /* Flashing */
};
static const Handler kExit[Demo_TrafficLight_StateCount] = {
    NULL,   /* Off */
    NULL,   /* Operating */
    Exit_Red,   /* Red */
    Exit_Green,   /* Green */
    Exit_Yellow,   /* Yellow */
    Exit_Flashing,   /* Flashing */
};
/* owner, initial target, initial action; row r - 1 describes region r */
static const struct { Demo_TrafficLight_State owner; Demo_TrafficLight_State initial; Handler action; } kRegions[Demo_TrafficLight_RegionCount - 1] = {
    { Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_Red, NULL },   /* region 1 */
};

static void OnEntry(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    if (kEntry[state] != NULL) {
        kEntry[state](m);
    }
}

static void OnExit(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    if (kExit[state] != NULL) {
        kExit[state](m);
    }
}

static Demo_TrafficLight_State Innermost(const Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    while (state != Demo_TrafficLight_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Demo_TrafficLight_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Demo_TrafficLight_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Demo_TrafficLight_Trace_Exit, Demo_TrafficLight_StateName(state));
    OnExit(m, state);
    m->active[RegionOf(state)] = Demo_TrafficLight_State_None;
    m->history[RegionOf(state)] = state;
}

static void EnterState(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Demo_TrafficLight_Trace_Enter, Demo_TrafficLight_StateName(state));
    OnEntry(m, state);
}

static void EnterRegion(Demo_TrafficLight* m, size_t region) {
    if (kRegions[region - 1].action != NULL) {
        kRegions[region - 1].action(m);
    }
    EnterDown(m, kRegions[region - 1].owner, kRegions[region - 1].initial, false);
}

static void EnterDefault(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterHistory(Demo_TrafficLight* m, Demo_TrafficLight_State state, bool deep) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        const Demo_TrafficLight_State remembered = m->history[region];
        if (remembered == Demo_TrafficLight_State_None) {
            EnterRegion(m, region);
        } else if (deep) {
            EnterState(m, remembered);
            EnterHistory(m, remembered, true);
        } else {
            EnterDown(m, state, remembered, false);
        }
    }
}

static void EnterDown(Demo_TrafficLight* m, Demo_TrafficLight_State from, Demo_TrafficLight_State target, bool history) {
    Demo_TrafficLight_State state = target;
    Demo_TrafficLight_State next = Demo_TrafficLight_State_None;
    while (Demo_TrafficLight_ParentOf(state) != from) {
        next = state;
        state = Demo_TrafficLight_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Demo_TrafficLight_State_None) {
        if (history) {
            EnterHistory(m, state, kHistoryKind[state] == 2);
            return;
        }
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target, history);
}

typedef bool (*GuardFn)(Demo_TrafficLight* m);

static void Transition_2(Demo_TrafficLight* m) {
    m->hooks->logFault(m->context);
}

static void Transition_5(Demo_TrafficLight* m) {
    m->hooks->shortenGreen(m->context);
}

typedef struct {
    Demo_TrafficLight_State source;
    Demo_TrafficLight_Event event;
    GuardFn guard;
    Handler action;
    Demo_TrafficLight_State target;   /* None for internal transitions */
    Demo_TrafficLight_State lca;
    bool history;       /* enter target through its history */
    const char* name;
} TransitionRow;

/* source, event, guard, action, target, least common ancestor, history, trace name */
static const TransitionRow kTransitions[9] = {
    { Demo_TrafficLight_State_Off, Demo_TrafficLight_Event_PowerOn, NULL, NULL, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_None, false, "Off -> Operating" },
    { Demo_TrafficLight_State_Operating, Demo_TrafficLight_Event_PowerOff, NULL, NULL, Demo_TrafficLight_State_Off, Demo_TrafficLight_State_None, false, "Operating -> Off" },
    { Demo_TrafficLight_State_Operating, Demo_TrafficLight_Event_Fault, NULL, Transition_2, Demo_TrafficLight_State_Flashing, Demo_TrafficLight_State_None, false, "Operating -> Flashing" },
    { Demo_TrafficLight_State_Red, Demo_TrafficLight_Event_Timer, NULL, NULL, Demo_TrafficLight_State_Green, Demo_TrafficLight_State_Operating, false, "Red -> Green" },
    { Demo_TrafficLight_State_Green, Demo_TrafficLight_Event_Timer, NULL, NULL, Demo_TrafficLight_State_Yellow, Demo_TrafficLight_State_Operating, false, "Green -> Yellow" },
    { Demo_TrafficLight_State_Green, Demo_TrafficLight_Event_PedestrianRequest, NULL, Transition_5, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Operating, false, "Green (internal)" },
    { Demo_TrafficLight_State_Yellow, Demo_TrafficLight_Event_Timer, NULL, NULL, Demo_TrafficLight_State_Red, Demo_TrafficLight_State_Operating, false, "Yellow -> Red" },
    { Demo_TrafficLight_State_Flashing, Demo_TrafficLight_Event_Repair, NULL, NULL, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_None, true, "Flashing -> Operating (history)" },
    { Demo_TrafficLight_State_Flashing, Demo_TrafficLight_Event_PowerOff, NULL, NULL, Demo_TrafficLight_State_Off, Demo_TrafficLight_State_None, false, "Flashing -> Off" },
};

static bool TryRow(Demo_TrafficLight* m, const TransitionRow* row) {
    if (row->guard != NULL && !row->guard(m)) {
        return false;
    }
    Trace(m, Demo_TrafficLight_Trace_Transition, row->name);
    if (row->target == Demo_TrafficLight_State_None) {
        if (row->action != NULL) {
            row->action(m);
        }
        return true;
    }
    Demo_TrafficLight_State root = row->source;
    while (Demo_TrafficLight_ParentOf(root) != row->lca) {
        root = Demo_TrafficLight_ParentOf(root);
    }
    ExitState(m, root);
    if (row->action != NULL) {
        row->action(m);
    }
    EnterDown(m, row->lca, row->target, row->history);
    return true;
}

static bool HandleEvent(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event) {
    size_t i;
    for (i = 0; i < 9; ++i) {
        if (kTransitions[i].source == state && kTransitions[i].event == event && TryRow(m, &kTransitions[i])) {
            return true;
        }
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Demo_TrafficLight_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Demo_TrafficLight* m, Demo_TrafficLight_Event event) {
    Trace(m, Demo_TrafficLight_Trace_Event, Demo_TrafficLight_EventName(event));
    if (m->active[0] != Demo_TrafficLight_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    Trace(m, Demo_TrafficLight_Trace_Ignored, Demo_TrafficLight_EventName(event));
    return false;
}

void Demo_TrafficLight_Init(Demo_TrafficLight* m, const Demo_TrafficLight_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Demo_TrafficLight_RegionCount; ++i) {
        m->active[i] = Demo_TrafficLight_State_None;
        m->history[i] = Demo_TrafficLight_State_None;
    }
}

void Demo_TrafficLight_Start(Demo_TrafficLight* m) {
    size_t i;
    for (i = 0; i < Demo_TrafficLight_RegionCount; ++i) {
        m->active[i] = Demo_TrafficLight_State_None;
        m->history[i] = Demo_TrafficLight_State_None;
    }
    Trace(m, Demo_TrafficLight_Trace_Start, "TrafficLight");
    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Off, false);
}

bool Demo_TrafficLight_Dispatch(Demo_TrafficLight* m, Demo_TrafficLight_Event event) {
    bool handled = false;
    handled = DispatchCore(m, event);
    return handled;
}

Demo_TrafficLight_State Demo_TrafficLight_Current(const Demo_TrafficLight* m) {
    return Innermost(m, m->active[0]);
}

bool Demo_TrafficLight_IsIn(const Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    return state != Demo_TrafficLight_State_None && m->active[RegionOf(state)] == state;
}

bool Demo_TrafficLight_IsFinished(const Demo_TrafficLight* m) {
    return ((void)m, false);
}

